"""Fixed-prefix decode benchmark with explicit stage buffers and token feedback."""
from collections import Counter,deque
from concurrent.futures import ProcessPoolExecutor,as_completed
from dataclasses import asdict
import json
from pathlib import Path
import sys
sys.path.insert(0,'/Users/bytedance/codes/TokenSim')
from scripts.lpx.serving_bank import NativeServingBank
from scripts.lpx.serving_pipeline import ServingPipeline,ServingWorkload,ForwardTask
from scripts.lpx.mfu_metrics import useful_matrix_flops
from scripts.lpx.replay_profiles import source_identity
from scripts.search_lpx_mfu import build_cache
R=Path('outputs/lpx-maximum-mfu-20261103')
CONTEXT=101000
class SnapshotBank(NativeServingBank):
    def frame_key(self,task):return (1,CONTEXT)
    def admit(self,client,cycle):
        self.memory.admit(self.request_id(client,cycle),self.owner.domain,self.owner.instance,maximum_context=102000,current_context=CONTEXT)
class SnapshotPipeline(ServingPipeline):
    def __init__(self,bank,clients,rounds):
        super().__init__(bank,ServingWorkload(1,rounds,1,clients,1))
        self.input=deque(self.task(c) for c in range(clients));self.contexts=[[CONTEXT-1]*self.pp for _ in range(clients)]
        for c in range(clients):bank.admit(c,0)
    def task(self,client):return ForwardTask(client,0,CONTEXT-1,1,'decode',True)
    def finish(self,kind,task,stage):
        if kind!='head':
            super().finish(kind,task,stage)
            if kind=='body':self.contexts[task.client][stage]=CONTEXT-1
            return
        self.io=None;c=task.client;self.generated[c]+=1;n=self.generated[c]
        self.tokens.append(dict(client=c,token=n,time=self.now))
        if n<self.workload.outputs:self.input.append(self.task(c))
        else:self.bank.release(c,0)
    def benchmark(self,warm=8,measure=32):
        try:
            self.kernel.window(0);self.dispatch()
            while self.pending:
                done=self.kernel.advance();assert done is not None;self.now=done.end;self.finish(*self.pending.pop(done.id));self.dispatch()
            n=self.workload.clients;assert len(self.tokens)==n*self.workload.outputs
            assert self.counters['decode_tokens']==len(self.tokens) and not self.input and not any(self.reserved) and not any(t is not None for t in self.active+self.arrived)
            self.bank.validate_empty();lo=warm*n;hi=lo+measure*n;start=self.tokens[lo-1]['time'];middle=self.tokens[lo+measure*n//2-1]['time'];end=self.tokens[hi-1]['time'];tokens=self.tokens[lo:hi];counts=Counter(t['client'] for t in tokens)
            return dict(resident_requests=n,aggregate_tps=len(tokens)/(end-start),measured_tokens=len(tokens),measured_seconds=end-start,per_client_completions=dict(counts),warmup_rounds=warm,measured_rounds=measure,drained_rounds=self.workload.outputs,elapsed_full_drain_s=self.now,convergence=dict(earlier_half_tps=(measure*n//2)/(middle-start),later_half_tps=(measure*n-measure*n//2)/(end-middle)),maximum_reserved_input_slots=self.max_pending,all_leases_released=True,all_stage_buffers_empty=True)
        finally:self.kernel.close()
def run(pp):
    build_cache();identity=source_identity();cfg=json.loads((R/'shared-kv-split-dot/result.json').read_text())['config'];caps=json.loads((R/'shared-kv-family-capacity.json').read_text())['rows'];row=next(r for r in caps if(r['tp'],r['kvp'],r['kv_parallel_layers'],r['workspace'])==(16,4,'full_attention','conservative'));n=row['maximum_resident_by_pp'][str(pp)]
    folder=R/f'shared-kv-buffered-resident-pp{pp}';bank=SnapshotBank(cfg,ServingWorkload(CONTEXT,80,1,n,1),tp=16,kvp=4,pp=pp,pool_chips=3,cache=folder/'profiles',global_kv_layout='value_rope_fp8');bank.contexts={(1,CONTEXT):[CONTEXT]}
    result=SnapshotPipeline(bank,n,80).benchmark();peak=bank.chips*315e15/256;work=useful_matrix_flops(bank.model,CONTEXT)['total'];mfu=100*result['aggregate_tps']*work/peak
    report=dict(config=cfg,bank=bank.describe(),replay=result,mfu_percent=mfu,useful_flops_per_token=work,source_sha256=identity,scope='Experimental shared cache; fixed 101K prefix snapshot repeated, matching the existing resident-prefix throughput convention. Native whole-buffer transformer parts, explicit stage entry and handoff, one active plus one incoming chunk per stage, greedy token feedback, 102K SRAM lease admission and complete drain. No production prefill, cache-growth workload, matching quality or physical compiler claim.')
    (folder/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(dict(pp=pp,n=n,mfu=mfu,tps=result['aggregate_tps'],convergence=result['convergence'])),flush=True);return report
if __name__=='__main__':
    with ProcessPoolExecutor(max_workers=2) as pool:
        rows=[f.result() for f in as_completed([pool.submit(run,pp) for pp in (10,12,15,20)])]
    (R/'shared-kv-buffered-resident.json').write_text(json.dumps(dict(results=rows,expected=4),indent=2)+'\n')

