from collections import Counter,deque
import json,math,sys
from pathlib import Path
sys.path.insert(0,'/Users/bytedance/codes/TokenSim')
from scripts.bound_lpx_mfu_layouts import saved_profile
from scripts.lpx.mfu_metrics import critical_path_seconds
R=Path('outputs/lpx-maximum-mfu-20261103')
def demand(nodes):
    children=[[] for _ in nodes];degree=[len(n.predecessors) for n in nodes]
    for i,n in enumerate(nodes):
        for p in n.predecessors:children[p].append(i)
    ready=deque(i for i,d in enumerate(degree) if not d);order=[]
    while ready:
        i=ready.popleft();order.append(i)
        for c in children[i]:
            degree[c]-=1
            if not degree[c]:ready.append(c)
    assert len(order)==len(nodes);totals=Counter();held=[]
    for i,node in enumerate(nodes):
        seconds=node.occupancy
        if node.release_after is not None:
            end={i:node.duration}
            for j in order:
                if j==i:continue
                value=max((end[p] for p in nodes[j].predecessors if p in end),default=-math.inf)
                if value!=-math.inf:end[j]=value+nodes[j].delay+nodes[j].duration
                if j==node.release_after:break
            assert node.release_after in end;seconds=end[node.release_after];held.append(dict(index=i,resources=node.resources,seconds=seconds))
        for resource in node.resources:totals[resource]+=seconds
    return totals,held

def run(folder):
    path=R/folder;r=json.loads((path/'result.json').read_text());metas=r.get('programs',[r.get('program')]);metas=[m for m in metas if m]
    n=r.get('resident_requests',r.get('native_transformer',{}).get('resident_requests'));all_demand=Counter();holds=[];paths=[]
    for i,m in enumerate(metas):
        name=f'program-slot-{i}.json.gz' if 'programs' in r else 'program.json.gz';profile=saved_profile(path/name,m['input_sha256']);d,h=demand(profile.nodes);count=sum(c%len(metas)==i for c in range(n));all_demand.update({k:v*count for k,v in d.items()});holds.extend(h);paths.append(critical_path_seconds(profile.nodes))
    resource=max(all_demand,key=all_demand.get);bound=min(n/max(paths),n/all_demand[resource]);report=dict(folder=folder,resident=n,busiest_resource=resource,resource_seconds_per_round=all_demand[resource],aggregate_tps_upper=bound,mfu_percent_upper=100*bound*129261109248/((r.get('chips',163))*315e15/256),holds=holds)
    (path/'lifetime-bound.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='holds'}),flush=True)
if __name__=='__main__':
 for folder in sys.argv[1:]:run(folder)
